    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(NAVY);prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);if(!prefs.contains("user"))createUser();else showLogin();}
    private void createUser(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(20),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);l.addView(tv("RgaPro",32,NAVY,true));l.addView(tv("Bienvenido · acceso seguro",22,TEXT,true));EditText u=edit("Usuario"),p=edit("Clave de 6 dígitos"),p2=edit("Repite la clave");p.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);p2.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);l.addView(u,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p2,new LinearLayout.LayoutParams(-1,dp(52)));Button go=action("Crear acceso",true);l.addView(go,new LinearLayout.LayoutParams(-1,dp(56)));go.setOnClickListener(v->{if(u.getText().toString().trim().isEmpty()||!p.getText().toString().matches("\\d{6}")||!p.getText().toString().equals(p2.getText().toString())){Toast.makeText(this,"Usa una clave de 6 dígitos y repítela",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("user",u.getText().toString().trim()).putString("pin",p.getText().toString()).putBoolean("biometric",true).apply();currentUser=u.getText().toString().trim();home();});l.addView(tv("🔒 Los datos se mantienen en el dispositivo.",13,MUTED,false));setContentView(l);}
    private void showLogin(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(20),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);l.addView(tv("RgaPro",32,NAVY,true));l.addView(tv("Acceso a tu cartera",22,TEXT,true));l.addView(tv("Clave + biometría",15,MUTED,false));Button key=action("🔐 Entrar con clave",true),bio=action("● Entrar con huella / biometría",false);l.addView(key,new LinearLayout.LayoutParams(-1,dp(56)));l.addView(bio,new LinearLayout.LayoutParams(-1,dp(56)));key.setOnClickListener(v->login());bio.setOnClickListener(v->biometricLogin());setContentView(l);}
    private void login(){EditText e=edit("Clave de 6 dígitos");e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog d=new AlertDialog.Builder(this).setTitle("Entrar").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(prefs.getString("pin","").equals(e.getText().toString())){d.dismiss();currentUser=prefs.getString("user","");home();}else e.setError("Clave incorrecta");}));d.show();}
    private void biometricLogin(){if(!prefs.getBoolean("biometric",true)){Toast.makeText(this,"Biometría desactivada",Toast.LENGTH_SHORT).show();return;}int r=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_WEAK);if(r!=BiometricManager.BIOMETRIC_SUCCESS){Toast.makeText(this,"Biometría no disponible. Usa la clave.",Toast.LENGTH_LONG).show();return;}BiometricPrompt p=new BiometricPrompt(this,biometricExecutor,new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(()->{currentUser=prefs.getString("user","");home();});}});p.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("RgaPro").setSubtitle("Acceso seguro").setNegativeButtonText("Usar clave").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_WEAK).build());}
    private void home(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout top=col();top.setBackgroundColor(NAVY);top.setGravity(Gravity.CENTER);top.addView(tv("RgaPro",28,Color.WHITE,true));top.addView(tv("Bienvenido, "+currentUser+" 👋",17,Color.WHITE,false));root.addView(top,new LinearLayout.LayoutParams(-1,dp(110)));ScrollView sc=new ScrollView(this);LinearLayout body=col();body.setPadding(dp(18),dp(18),dp(18),dp(20));body.addView(tv("¿Qué quieres hacer hoy?",22,TEXT,true));menu(body,"👤","Clientes","Buscar por nombre, DNI, teléfono, email o póliza",v->clients());menu(body,"▣","Pólizas","Auto · hogar · vida · salud · decesos · otros",v->policies());menu(body,"▤","Documentos","DNI doble cara · varias páginas · JPEG · PDF · OCR",v->scanDocument());menu(body,"🔔","Vencimientos","60 · 45 · 30 · 15 días",v->expiries());menu(body,"🔒","Seguridad","Clave, biometría y compartir solo cuando tú quieras",v->security());sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button out=action("Cerrar sesión",false);root.addView(out,new LinearLayout.LayoutParams(-1,dp(52)));out.setOnClickListener(v->showLogin());setContentView(root);}
    private void menu(LinearLayout b,String icon,String title,String sub,View.OnClickListener c){LinearLayout x=new LinearLayout(this);x.setGravity(Gravity.CENTER_VERTICAL);x.setPadding(dp(12),dp(8),dp(12),dp(8));x.setBackground(bg(Color.WHITE,18));x.addView(tv(icon,28,BLUE,true),new LinearLayout.LayoutParams(dp(48),dp(68)));LinearLayout w=col();w.addView(tv(title,18,TEXT,true));w.addView(tv(sub,13,MUTED,false));x.addView(w,new LinearLayout.LayoutParams(0,dp(68),1));x.addView(tv("›",30,MUTED,false),new LinearLayout.LayoutParams(dp(28),dp(68)));x.setOnClickListener(c);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(86));p.bottomMargin=dp(10);b.addView(x,p);}
    private void page(String title,String sub){LinearLayout r=col();r.setBackgroundColor(BG);LinearLayout h=col();h.setBackgroundColor(NAVY);h.setPadding(dp(16),dp(10),dp(16),dp(10));Button back=action("‹",false);back.setTextColor(Color.WHITE);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->home());h.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));h.addView(tv(title,20,Color.WHITE,true));h.addView(tv(sub,12,Color.WHITE,false));r.addView(h);content=col();content.setPadding(dp(16),dp(16),dp(16),dp(20));ScrollView s=new ScrollView(this);s.addView(content);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
    private JSONArray data(){try{return new JSONArray(prefs.getString("policies","[]"));}catch(Exception e){return new JSONArray();}}
    private void save(JSONArray a){prefs.edit().putString("policies",a.toString()).apply();}
    private void clients(){page("Clientes","Busca por cualquier dato");EditText q=edit("Nombre, DNI, teléfono, email, póliza…");content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=col();content.addView(list);Runnable r=()->{list.removeAllViews();JSONArray a=data();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,q.getText().toString())){Button x=action("👤 "+p.optString("holder","Sin titular")+"\n"+p.optString("type","Cliente")+" · "+p.optString("number",""),false);x.setOnClickListener(v->detail(p));list.addView(x,new LinearLayout.LayoutParams(-1,dp(72)));}}};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){r.run();}public void afterTextChanged(android.text.Editable e){}});r.run();}
    private boolean match(JSONObject p,String q){if(q==null||q.trim().isEmpty())return true;String n=q.toLowerCase(Locale.ROOT);for(String k:new String[]{"holder","name","surname","birthDate","holderDni","phone","email","address","birthPlace","nationality","sex","parents","supportNumber","issueDate","expiry","type","number","ocrText","members","documentPhotos"})if(p.optString(k).toLowerCase(Locale.ROOT).contains(n))return true;return false;}
    private void detail(JSONObject p){StringBuilder s=new StringBuilder();s.append("Titular: ").append(p.optString("holder","—"));s.append("\nApellidos: ").append(p.optString("surname","—"));s.append("\nNombre: ").append(p.optString("name","—"));s.append("\nDNI/NIE: ").append(p.optString("holderDni","—"));s.append("\nNacimiento: ").append(p.optString("birthDate","—"));s.append("\nNacionalidad: ").append(p.optString("nationality","—"));s.append("\nSexo: ").append(p.optString("sex","—"));s.append("\nDomicilio: ").append(p.optString("address","—"));s.append("\nLugar nacimiento: ").append(p.optString("birthPlace","—"));s.append("\nPadres: ").append(p.optString("parents","—"));s.append("\nNº soporte: ").append(p.optString("supportNumber","—"));s.append("\nEmisión: ").append(p.optString("issueDate","—"));s.append("\nValidez: ").append(p.optString("validityDate",p.optString("expiry","—")));s.append("\nPóliza: ").append(p.optString("number","—"));s.append("\nTipo: ").append(p.optString("type","—"));s.append("\nFotos/documentos: ").append(p.optJSONArray("documentPhotos")!=null?p.optJSONArray("documentPhotos").length():0);new AlertDialog.Builder(this).setTitle("Ficha de cliente").setMessage(s.toString()).setPositiveButton("Cerrar",null).show();}
    private void policies(){page("Pólizas","Separadas por tipo");Spinner sp=new Spinner(this);String[] types={"Todas","Auto","Hogar","Vida","Salud","Decesos","Otros"};sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));content.addView(sp,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout list=col();content.addView(list);Runnable r=()->{list.removeAllViews();String f=String.valueOf(sp.getSelectedItem());JSONArray a=data();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&(f.equals("Todas")||f.equalsIgnoreCase(p.optString("type","Otros")))){Button x=action(p.optString("type","Otros")+" · "+p.optString("holder","Sin titular")+"\n"+p.optString("number","—")+" · "+p.optString("expiry","—"),false);x.setOnClickListener(v->detail(p));list.addView(x,new LinearLayout.LayoutParams(-1,dp(72)));}}};sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> a){}});r.run();}
    private void expiries(){page("Próximos vencimientos","60 · 45 · 30 · 15 días");JSONArray a=data();SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ROOT);Date now=new Date();boolean any=false;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);try{String ex=p.optString("expiry",p.optString("validityDate"));long d=(f.parse(ex).getTime()-now.getTime())/(86400000L);if(d>=0&&d<=60){any=true;content.addView(tv(p.optString("holder","Sin titular")+" · "+p.optString("type","Otros")+" · "+d+" días",17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(64)));}}catch(Exception ignored){}}if(!any)content.addView(tv("No hay pólizas en los próximos 60 días.",16,MUTED,false));}
    private void security(){page("Seguridad","Tú decides");Switch b=new Switch(this);b.setText("Permitir acceso biométrico");b.setChecked(prefs.getBoolean("biometric",true));content.addView(b,new LinearLayout.LayoutParams(-1,dp(58)));b.setOnCheckedChangeListener((x,v)->prefs.edit().putBoolean("biometric",v).apply());Button test=action("Probar biometría",false);content.addView(test,new LinearLayout.LayoutParams(-1,dp(54)));test.setOnClickListener(v->biometricLogin());content.addView(tv("No se comparte nada automáticamente. Las fotos y datos se guardan localmente.",13,MUTED,false));}
    private void scanDocument(){page("Escanear documento","DNI doble cara · multipágina · JPEG · PDF");content.addView(tv("DNI: se captura anverso y después reverso. La MRZ del reverso completa automáticamente nombre, apellidos, DNI y fechas. Cada foto queda vinculada al cliente detectado.",15,MUTED,false));Button dni=action("🪪 DNI · anverso + reverso",true);content.addView(dni,new LinearLayout.LayoutParams(-1,dp(56)));dni.setOnClickListener(v->{resetSession();dniMode=true;multiMode=false;openCamera();});Button multi=action("📷 Documento de varias páginas",false);content.addView(multi,new LinearLayout.LayoutParams(-1,dp(56)));multi.setOnClickListener(v->{resetSession();dniMode=false;multiMode=true;openCamera();});Button jpg=action("🖼 JPEG/JPG · una o varias fotos",false);content.addView(jpg,new LinearLayout.LayoutParams(-1,dp(56)));jpg.setOnClickListener(v->{resetSession();pickImages();});Button pdf=action("📄 PDF · todas las páginas",false);content.addView(pdf,new LinearLayout.LayoutParams(-1,dp(56)));pdf.setOnClickListener(v->{resetSession();pickPdf();});}
    private void resetSession(){sessionPaths.clear();sessionTexts.clear();dniSide=0;}
    private void openCamera(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA_REQ);return;}try{File d=new File(getCacheDir(),"scans");if(!d.exists())d.mkdirs();scanFile=File.createTempFile("rgapro_",".jpg",d);scanUri=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",scanFile);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,scanUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,CAMERA_REQ);}catch(Exception e){Toast.makeText(this,"No se pudo abrir la cámara",Toast.LENGTH_LONG).show();}}
    private void pickImages(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMAGE_REQ);}
    private void pickPdf(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PDF_REQ);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK)return;try{if(request==CAMERA_REQ){String path=copyFileToSession(scanFile);if(path==null)throw new IOException("No se pudo guardar la foto");sessionPaths.add(path);if(dniMode){if(dniSide==0){dniSide=1;processLastImage(true);}else processLastImage(false);}else processLastImage(false);}else if(request==IMAGE_REQ&&data!=null){if(data.getClipData()!=null){ClipData c=data.getClipData();for(int i=0;i<c.getItemCount();i++){String p=copyUriToSession(c.getItemAt(i).getUri(),"jpg");if(p!=null)sessionPaths.add(p);}}else if(data.getData()!=null){String p=copyUriToSession(data.getData(),"jpg");if(p!=null)sessionPaths.add(p);}processAllImages(0,new StringBuilder());}else if(request==PDF_REQ&&data!=null){Uri u=data.getData();String pdfPath=copyUriToSession(u,"pdf");if(pdfPath!=null)sessionPaths.add(pdfPath);Toast.makeText(this,"Leyendo PDF…",Toast.LENGTH_SHORT).show();PdfOcrHelper.process(this,u,new PdfOcrHelper.Callback(){public void onSuccess(String text){runOnUiThread(()->{sessionTexts.add(text);showOcrResult(text);});}public void onError(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"No se pudo leer el PDF. Comprueba que no esté protegido.",Toast.LENGTH_LONG).show());}});}}catch(Exception e){Toast.makeText(this,"No se pudo procesar el documento: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void processLastImage(boolean askBack){processImageFile(sessionPaths.get(sessionPaths.size()-1),new ImageCallback(){public void ok(String text){sessionTexts.add(text);if(askBack){runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("Anverso leído").setMessage("Ahora fotografía el REVERSO del DNI. Se guardarán ambas caras en el mismo cliente.").setNegativeButton("Cancelar",(d,w)->resetSession()).setPositiveButton("Fotografiar reverso",(d,w)->openCamera()).show());}else if(dniMode){showOcrResult(joinTexts());}else askMorePages();}public void error(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"No se pudo leer la foto: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
    private void askMorePages(){new AlertDialog.Builder(this).setTitle("Página procesada").setMessage("Puedes añadir otra foto al mismo documento o terminar y revisar todos los datos detectados.").setNegativeButton("Terminar",(d,w)->showOcrResult(joinTexts())).setPositiveButton("Añadir otra página",(d,w)->openCamera()).show();}
    private String joinTexts(){StringBuilder s=new StringBuilder();for(int i=0;i<sessionTexts.size();i++)s.append("\n--- DOCUMENTO ").append(i+1).append(" ---\n").append(sessionTexts.get(i)).append('\n');return s.toString();}
    private void processAllImages(int index,StringBuilder all){if(index>=sessionPaths.size()){showOcrResult(all.toString());return;}processImageFile(sessionPaths.get(index),new ImageCallback(){public void ok(String text){sessionTexts.add(text);all.append("\n--- IMAGEN ").append(index+1).append(" ---\n").append(text).append('\n');processAllImages(index+1,all);}public void error(Exception e){processAllImages(index+1,all);}});}
    private interface ImageCallback{void ok(String text);void error(Exception e);}
    private void processImageFile(String path,ImageCallback cb){new Thread(()->{try{BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;Bitmap bm=BitmapFactory.decodeFile(path,o);if(bm==null)throw new IOException("Imagen no válida");InputImage image=InputImage.fromBitmap(bm,0);TextRecognizer rec=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);rec.process(image).addOnSuccessListener(r->{String text=r.getText();bm.recycle();rec.close();cb.ok(text);}).addOnFailureListener(e->{bm.recycle();rec.close();cb.error(e);});}catch(Exception e){cb.error(e);}}).start();}
    private String copyFileToSession(File source)throws IOException{File dir=new File(getFilesDir(),"documents");if(!dir.exists())dir.mkdirs();File out=new File(dir,"scan_"+System.currentTimeMillis()+".jpg");copy(source,out);return out.getAbsolutePath();}
    private String copyUriToSession(Uri uri,String ext){try{File dir=new File(getFilesDir(),"documents");if(!dir.exists())dir.mkdirs();File out=new File(dir,"doc_"+System.currentTimeMillis()+"."+ext);InputStream in=getContentResolver().openInputStream(uri);if(in==null)return null;FileOutputStream os=new FileOutputStream(out);byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)os.write(buf,0,n);in.close();os.close();return out.getAbsolutePath();}catch(Exception e){return null;}}
    private void copy(File a,File b)throws IOException{FileInputStream in=new FileInputStream(a);FileOutputStream out=new FileOutputStream(b);byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();out.close();}

    private static class OcrData{String holder="",surname="",name="",dni="",birthDate="",nationality="",sex="",address="",birthPlace="",parents="",supportNumber="",issueDate="",validityDate="",phone="",email="";}
    private OcrData parseOcr(String raw){OcrData d=new OcrData();String text=raw==null?"":raw.replace('\r','\n');String norm=text.toUpperCase(Locale.ROOT);Matcher md=Pattern.compile("\\b(?:[0-9]{8}[A-Z]|[XYZ][0-9]{7}[A-Z])\\b").matcher(norm);if(md.find())d.dni=md.group();Matcher mrz=Pattern.compile("IDESP[^\\n\\r]*",Pattern.CASE_INSENSITIVE).matcher(norm);if(mrz.find()){Matcher x=Pattern.compile("IDESP([0-9]{8}[A-Z])").matcher(mrz.group());if(x.find())d.dni=x.group(1);}String[] lines=norm.split("\\n");for(int i=0;i<lines.length;i++){String line=clean(lines[i]);if(line.isEmpty())continue;if(line.startsWith("APELLIDOS")){d.surname=valueAfterLabel(line,"APELLIDOS");if(d.surname.isEmpty()&&i+1<lines.length)d.surname=clean(lines[i+1]);}else if(line.startsWith("NOMBRE")){d.name=valueAfterLabel(line,"NOMBRE");if(d.name.isEmpty()&&i+1<lines.length)d.name=clean(lines[i+1]);}else if(line.contains("NACIONALIDAD")){d.nationality=valueAfterLabel(line,"NACIONALIDAD");}else if(line.startsWith("SEXO")){d.sex=valueAfterLabel(line,"SEXO");}else if(line.contains("DOMICILIO")){d.address=valueAfterLabel(line,"DOMICILIO");if(d.address.isEmpty())d.address=nextValue(lines,i);}else if(line.contains("LUGAR DE NACIMIENTO")){d.birthPlace=valueAfterLabel(line,"LUGAR DE NACIMIENTO");if(d.birthPlace.isEmpty())d.birthPlace=nextValue(lines,i);}else if(line.contains("HIJO/A DE")||line.contains("HIJO DE")){String lab=line.contains("HIJO/A DE")?"HIJO/A DE":"HIJO DE";d.parents=valueAfterLabel(line,lab);if(d.parents.isEmpty())d.parents=nextValue(lines,i);}else if(line.contains("NUM SOPORTE")||line.contains("Nº SOPORTE")||line.contains("N° SOPORTE")){String lab=line.contains("NUM SOPORTE")?"NUM SOPORTE":line.contains("Nº SOPORTE")?"Nº SOPORTE":"N° SOPORTE";d.supportNumber=valueAfterLabel(line,lab);if(d.supportNumber.isEmpty())d.supportNumber=nextValue(lines,i);}if(line.contains("EMISION")){String z=firstDate(line);if(!z.isEmpty())d.issueDate=z;}if(line.contains("VALIDEZ")||line.contains("CADUCIDAD")){String z=firstDate(line);if(!z.isEmpty())d.validityDate=z;}}
        Matcher mname=Pattern.compile("([A-ZÁÉÍÓÚÑ]+)<([A-ZÁÉÍÓÚÑ]+)<<([A-ZÁÉÍÓÚÑ]+)").matcher(norm);if(mname.find()){if(d.surname.isEmpty())d.surname=mname.group(1)+" "+mname.group(2);if(d.name.isEmpty())d.name=mname.group(3);}Matcher mdate=Pattern.compile("(\\d{6})\\d[MF](\\d{6})").matcher(norm.replace("<",""));if(mdate.find()){if(d.birthDate.isEmpty())d.birthDate=mrzDate(mdate.group(1));if(d.validityDate.isEmpty())d.validityDate=mrzDate(mdate.group(2));}if(d.birthDate.isEmpty()){Matcher bd=Pattern.compile("(?:NACIMIENTO|NAC)\\s*[:.-]?\\s*(\\d{2}[ /.-]\\d{2}[ /.-]\\d{4})").matcher(norm);if(bd.find())d.birthDate=bd.group(1).replace('-','/').replace('.','/');}if(d.surname.isEmpty()&&d.name.isEmpty()){Matcher f=Pattern.compile("\\b([A-ZÁÉÍÓÚÑ]{3,})\\s+([A-ZÁÉÍÓÚÑ]{3,})\\s+([A-ZÁÉÍÓÚÑ]{3,})\\b").matcher(norm);if(f.find()){d.surname=f.group(1)+" "+f.group(2);d.name=f.group(3);}}d.holder=(d.name+" "+d.surname).trim();return d;}
    private String clean(String s){return s==null?"":s.trim().replaceAll("\\s+"," ");}
    private String valueAfterLabel(String s,String label){int p=s.indexOf(label);if(p<0)return "";return s.substring(p+label.length()).replaceFirst("^[ :.-]+","").trim();}
    private String nextValue(String[] lines,int i){return i+1<lines.length?clean(lines[i+1]):"";}
    private String firstDate(String s){Matcher m=Pattern.compile("\\d{2}[ /.-]\\d{2}[ /.-]\\d{4}").matcher(s);return m.find()?m.group():"";}
    private String mrzDate(String yyMMdd){try{int yy=Integer.parseInt(yyMMdd.substring(0,2));int year=yy<=30?2000+yy:1900+yy;return String.format(Locale.ROOT,"%02d/%02d/%04d",Integer.parseInt(yyMMdd.substring(4,6)),Integer.parseInt(yyMMdd.substring(2,4)),year);}catch(Exception e){return "";}}

    private void showOcrResult(String raw){OcrData d=parseOcr(raw);LinearLayout box=col();box.setPadding(dp(10),dp(4),dp(10),dp(4));box.addView(tv("Se han procesado "+sessionPaths.size()+" documento(s). Revisa y corrige antes de guardar. El texto completo del OCR también se conserva.",14,MUTED,false));EditText holder=edit("Titular / nombre completo"),surname=edit("Apellidos"),name=edit("Nombre"),dni=edit("DNI / NIE"),birth=edit("Fecha de nacimiento"),nationality=edit("Nacionalidad"),sex=edit("Sexo"),address=edit("Domicilio"),birthPlace=edit("Lugar de nacimiento"),parents=edit("Padres"),support=edit("Nº soporte"),issue=edit("Fecha de emisión"),validity=edit("Fecha de validez / caducidad"),phone=edit("Teléfono"),email=edit("Email"),number=edit("Nº póliza");holder.setText(d.holder);surname.setText(d.surname);name.setText(d.name);dni.setText(d.dni);birth.setText(d.birthDate);nationality.setText(d.nationality);sex.setText(d.sex);address.setText(d.address);birthPlace.setText(d.birthPlace);parents.setText(d.parents);support.setText(d.supportNumber);issue.setText(d.issueDate);validity.setText(d.validityDate);for(EditText e:new EditText[]{holder,surname,name,dni,birth,nationality,sex,address,birthPlace,parents,support,issue,validity,phone,email,number})box.addView(e,new LinearLayout.LayoutParams(-1,dp(52)));Spinner type=new Spinner(this);String[] types={"Cliente / DNI","Auto","Hogar","Vida","Salud","Decesos","Otros"};type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));box.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));ScrollView sc=new ScrollView(this);sc.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Datos detectados por OCR").setView(sc).setNegativeButton("Descartar",null).setPositiveButton("Guardar cliente",null).create();dialog.setOnShowListener(q->dialog.getButton(-1).setOnClickListener(v->{saveClient(holder,surname,name,dni,birth,nationality,sex,address,birthPlace,parents,support,issue,validity,phone,email,number,String.valueOf(type.getSelectedItem()),raw);dialog.dismiss();}));dialog.show();}
    private void saveClient(EditText holder,EditText surname,EditText name,EditText dni,EditText birth,EditText nationality,EditText sex,EditText address,EditText birthPlace,EditText parents,EditText support,EditText issue,EditText validity,EditText phone,EditText email,EditText number,String type,String raw){try{JSONArray a=data();String key=dni.getText().toString().trim().toUpperCase(Locale.ROOT);int idx=-1;if(!key.isEmpty()){for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&key.equalsIgnoreCase(p.optString("holderDni",""))){idx=i;break;}}}if(idx<0&&!holder.getText().toString().trim().isEmpty()){for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&holder.getText().toString().trim().equalsIgnoreCase(p.optString("holder",""))){idx=i;break;}}}JSONObject p=idx>=0?a.optJSONObject(idx):new JSONObject();p.put("holder",holder.getText().toString().trim());p.put("surname",surname.getText().toString().trim());p.put("name",name.getText().toString().trim());p.put("holderDni",key);p.put("birthDate",birth.getText().toString().trim());p.put("nationality",nationality.getText().toString().trim());p.put("sex",sex.getText().toString().trim());p.put("address",address.getText().toString().trim());p.put("birthPlace",birthPlace.getText().toString().trim());p.put("parents",parents.getText().toString().trim());p.put("supportNumber",support.getText().toString().trim());p.put("issueDate",issue.getText().toString().trim());p.put("validityDate",validity.getText().toString().trim());p.put("expiry",validity.getText().toString().trim());p.put("phone",phone.getText().toString().trim());p.put("email",email.getText().toString().trim());p.put("number",number.getText().toString().trim());p.put("type",type);p.put("ocrText",raw);JSONArray docs=p.optJSONArray("documentPhotos");if(docs==null)docs=new JSONArray();for(int i=0;i<sessionPaths.size();i++){JSONObject doc=new JSONObject();doc.put("path",sessionPaths.get(i));doc.put("side",dniMode?(i==0?"ANVERSO":"REVERSO"):"DOCUMENTO "+(i+1));doc.put("addedAt",System.currentTimeMillis());docs.put(doc);}p.put("documentPhotos",docs);if(idx>=0)a.put(idx,p);else a.put(p);save(a);Toast.makeText(this,"Cliente guardado. "+sessionPaths.size()+" documento(s) asociados.",Toast.LENGTH_LONG).show();home();}catch(Exception e){Toast.makeText(this,"No se pudo guardar el cliente: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
